  openTerminal({deviceId}){const existingId=this.presentationByDevice.get(deviceId),existing=existingId?this.sessionOwner.tab(existingId):null;if(existing)return freeze({ok:true,provider:this.runtime.descriptor(),tab:existing,runtimeTruth:'INTERNAL_SIMULATION',reusedPresentation:true});const session=this.runtime.open(deviceId);const tab=this.sessionOwner.attachProviderSession(this.runtime,session.id,{classification:'REAL_RUNTIME_PROVIDER',evidenceRole:'Runs InternalSimulation runtime truth'});this.presentationByDevice.set(deviceId,tab.presentationId);return freeze({ok:true,provider:this.runtime.descriptor(),tab,runtimeTruth:'INTERNAL_SIMULATION',reusedPresentation:false})}
  input({deviceId,command,invocationId}){const presentationId=this.presentationByDevice.get(deviceId);if(!presentationId)throw Error('RUN_TERMINAL_NOT_OPEN');const tab=this.sessionOwner.tab(presentationId);return this.runtime.input(tab.runtimeSessionId,String(command||''),String(invocationId||`runs-${Date.now()}`))}
  disconnect(){const lifecycle=this.runtime.run.lifecycle;this.runtime.disconnect();return freeze({connected:false,epoch:this.runtime.epoch,lifecycle,runtimeTruth:'INTERNAL_SIMULATION',providerLossIsRunCompletion:false})}
  reconnect({deviceId}){const presentationId=this.presentationByDevice.get(deviceId);if(!presentationId)throw Error('RUN_TERMINAL_NOT_OPEN');const tab=this.sessionOwner.tab(presentationId);const session=this.runtime.reconnect(tab.runtimeSessionId);return freeze({connected:true,session:structuredClone(session),lifecycle:this.runtime.run.lifecycle,runtimeTruth:'INTERNAL_SIMULATION'})}
  pause(payload={}){return this.runtime.lifecycle('pause',payload)}
  resume(payload={}){return this.runtime.lifecycle('resume',payload)}
